// Smoke test for the packaged artifacts: code generated by the karkas-codegen tool installed from a
// local NuGet feed, compiled against the Karkas.Data / Karkas.Data.Sqlite packages from the same feed.
// Used by Karkas.Examples/TestBash/run_packaged_tool_sample_blog.bash
using System;
using System.Data.Common;
using Microsoft.Data.Sqlite;
using Karkas.Examples.SampleBlog.Bs;
using Karkas.Examples.SampleBlog.TypeLibrary;

DbProviderFactories.RegisterFactory("Microsoft.Data.Sqlite", SqliteFactory.Instance);

using DbConnection connection = new SqliteConnection("Data Source=sample-blog.sqlite;Mode=ReadWrite;");
BlogBs blogBs = new BlogBs(connection);

Blog blog = new Blog();
blog.Title = "Hello from packaged Karkas " + Guid.NewGuid();
blog.Content = "Generated by karkas-codegen from a local NuGet feed";
blog.CreatedDateTime = DateTime.UtcNow.ToString("O");

long blogId = blogBs.Insert(blog);
Check(blogId > 0 && blogId == blog.BlogId, "Insert returns identity");

Blog fromDb = blogBs.QueryByBlogId(blogId);
Check(fromDb != null && fromDb.Title == blog.Title && fromDb.Content == blog.Content, "QueryByBlogId");

fromDb.Title = "Updated " + Guid.NewGuid();
blogBs.Update(fromDb);
Check(blogBs.QueryByBlogId(blogId).Title == fromDb.Title, "Update");

blogBs.Delete(blogId);
Check(blogBs.QueryByBlogId(blogId) == null, "Delete");

Console.WriteLine($"Packaged Karkas works on {Environment.Version}");

static void Check(bool condition, string name)
{
	if (!condition)
	{
		throw new Exception($"{name} DOES NOT work");
	}
	Console.WriteLine($"{name} works");
}
